Position Interface::factoryPosition(Vector2 point)const{float tile=38*factoryZoom;return {int(std::floor(factoryCamera.x+(point.x-factoryView.x-factoryView.width*.5f)/tile)),int(std::floor(factoryCamera.y+(point.y-factoryView.y-factoryView.height*.5f)/tile))};}
Rectangle Interface::factoryTile(Position p)const{float tile=38*factoryZoom;return {factoryView.x+factoryView.width*.5f+(p.x-factoryCamera.x)*tile,factoryView.y+factoryView.height*.5f+(p.y-factoryCamera.y)*tile,tile,tile};}
void Interface::homeFactory(){
 if(!factory.at(factorySelected)&&!factory.machines.empty()){
  // Prefer a real single-dose source when opening a factory from an older layout.
  Position anchor=factory.machines.begin()->first;int best=100000000;
  for(auto& [p,m]:factory.machines){int score=std::abs(p.x+7)+std::abs(p.y-6);if(m.kind!=MachineKind::Feeder||m.automatic)score+=10000000;if(score<best){best=score;anchor=p;}}
  selectMachine(anchor);
 }
 std::set<Position> connected;std::vector<Position> queue{factorySelected};connected.insert(factorySelected);
 auto feeds=[](Position p,const Machine& m,Position q,const Machine& target){if(m.kind==MachineKind::Wall||target.kind==MachineKind::Wall||target.kind==MachineKind::Feeder||target.kind==MachineKind::RecipeKitchen)return false;return nextPosition(p,m.dir)==q||(hasSideOutlet(m.kind)&&nextPosition(p,(m.dir+1)%4)==q);};
 for(size_t i=0;i<queue.size();i++){auto p=queue[i];auto m=factory.at(p);if(!m)continue;for(int d=0;d<4;d++){auto q=nextPosition(p,d);auto n=factory.at(q);if(n&&!connected.count(q)&&(feeds(p,*m,q,*n)||feeds(q,*n,p,*m))){connected.insert(q);queue.push_back(q);}}}
 int left=factorySelected.x,right=left,top=factorySelected.y,bottom=top;
 for(auto p:connected){left=std::min(left,p.x);right=std::max(right,p.x);top=std::min(top,p.y);bottom=std::max(bottom,p.y);}
 // A long or remote network still opens at a useful working scale.
 if(right-left>7){left=factorySelected.x-3;right=factorySelected.x+4;}
 if(bottom-top>7){top=factorySelected.y-3;bottom=factorySelected.y+4;}
 int nearbyTop=top,nearbyBottom=bottom;
 for(auto& [p,m]:factory.machines)if(p.x>=left&&p.x<=right&&p.y>=top-4&&p.y<=bottom+2){nearbyTop=std::min(nearbyTop,p.y);nearbyBottom=std::max(nearbyBottom,p.y);}
 if(nearbyBottom-nearbyTop<=7){top=nearbyTop;bottom=nearbyBottom;}
 factoryCamera={(left+right+1)*.5f,(top+bottom+1)*.5f};
 float tile=std::min({76.f,factoryView.width/std::max(8.f,float(right-left+3)),factoryView.height/std::max(8.f,float(bottom-top+3))});
 factoryZoom=factoryZoomTarget=std::clamp(tile/38,.015f,3.f);factoryZooming=false;
}
void Interface::fitFactory(){if(factory.machines.empty()){homeFactory();return;}int left=1000001,top=1000001,right=-1000001,bottom=-1000001;for(auto& [p,m]:factory.machines){left=std::min(left,p.x);right=std::max(right,p.x);top=std::min(top,p.y);bottom=std::max(bottom,p.y);}for(const auto& [p,links]:factory.energyLinks){left=std::min(left,p.x);right=std::max(right,p.x);top=std::min(top,p.y);bottom=std::max(bottom,p.y);}factoryCamera={(left+right+1)*.5f,(top+bottom+1)*.5f};factoryZoom=factoryZoomTarget=std::clamp(std::min(factoryView.width/((right-left+2.5f)*38.f),factoryView.height/((bottom-top+2.5f)*38.f)),.015f,2.4f);factoryZooming=false;}
void Interface::saveFactoryCheckpoint(){auto original=factory.storageFile;factory.storageFile=original.parent_path()/"factory-checkpoint.json";bool saved=factory.save();factory.storageFile=original;factory.notice=saved?"Workspace checkpoint saved, including recipes and all live floor batches.":"Checkpoint could not be written.";}
void Interface::loadFactoryCheckpoint(){auto original=factory.storageFile;auto checkpoint=original.parent_path()/"factory-checkpoint.json";if(!std::filesystem::exists(checkpoint)&&!std::filesystem::exists(original)){factory.notice="No checkpoint yet. Save this workspace to create one.";return;}factory.storageFile=std::filesystem::exists(checkpoint)?checkpoint:original;bool loaded=factory.load();factory.storageFile=original;if(loaded){energyLinkSelected=false;floorTelemetry.clear();factory.notice="Workspace restored. The factory is paused.";factory.dirty=true;factoryAccumulator=0;referenceRecipe=0;}else factory.notice="Checkpoint could not be read. The current workspace was preserved.";}
void Interface::selectMachine(Position p){energyLinkSelected=false;auto links=factory.energyLinks.find(p);if(links!=factory.energyLinks.end()&&(!factory.at(p)||(factoryTab==0&&isEnergyConduit(factoryTool)))){selectedEnergyMedium=conduitMedium(isEnergyConduit(factoryTool)?factoryTool:energyConduit(links->second.front().medium));energyLinkSelected=factory.energyLink(p,selectedEnergyMedium)!=nullptr;}factorySelected=p;factoryTab=1;batchSlot=componentIndex=0;latticeSelected=-1;referenceRecipe=0;inspectorScroll=0;factoryStamp.reset();factoryErasing=factoryCopying=false;auto m=factory.at(p);dishName=m&&factory.dish(m->recipe)?factory.dish(m->recipe)->name:"Untitled dish";if(m&&(m->kind==MachineKind::Feeder||isDosingMachine(m->kind)||m->kind==MachineKind::SeedHopper||isFarmBed(m->kind))){sourceIngredient=m->ingredient;sourceDose=m->dose;doseText=roundTo(sourceDose,2);}}
const Batch* Interface::inspectedBatch()const{return referenceRecipe?nullptr:factory.batchAt(factorySelected,batchSlot);}
bool Interface::commitDose(){try{size_t used=0;double value=std::stod(doseText,&used);if(used!=doseText.size()||!std::isfinite(value)||value<.1||value>1000)throw std::invalid_argument("dose");sourceDose=value;doseText=roundTo(value,2);return true;}catch(...){doseText=roundTo(sourceDose,2);factory.notice="Enter a measured dose between 0.1 and 1000 grams.";return false;}}
void Interface::setSource(){auto machine=factory.at(factorySelected);if(machine&&(machine->kind==MachineKind::SeedHopper||isFarmBed(machine->kind))){if(ingredient(sourceIngredient).category!="Produce"){factory.notice="Farm equipment only accepts crop varieties.";return;}if(factory.setIngredient(factorySelected,sourceIngredient))factory.dirty=true;return;}if(!commitDose())return;if(factory.setIngredient(factorySelected,sourceIngredient)){factory.at(factorySelected)->dose=sourceDose;factory.dirty=true;}}
void Interface::armSource(MachineKind kind){if(kind!=MachineKind::SeedHopper&&!commitDose())return;if(kind==MachineKind::SeedHopper&&ingredient(sourceIngredient).category!="Produce"){factory.notice="Choose a produce crop before placing its seed hopper.";return;}factoryTool=kind;sourceBrushConfigured=true;factoryTab=0;factoryStamp.reset();factoryErasing=factoryCopying=false;factory.notice=kind==MachineKind::SeedHopper?"Place a real seed hopper for "+ingredient(sourceIngredient).name+".":"Place a real "+machineSpec(kind).name+" for "+roundTo(sourceDose)+" g "+ingredient(sourceIngredient).name+".";}
void Interface::recordSelectedDish(uint64_t expected){auto id=factory.recordDish(factorySelected,dishName,batchSlot,expected);if(id){referenceRecipe=0;dishName=factory.dish(id)->name;}}
void Interface::buildDishLine(uint64_t id){auto line=factory.productionLine(id);if(!line){factory.notice="This reference has no recorded physical layout. Recreate its stages with machines, then record a new dish at a tasting dock.";return;}factoryStamp=*line;factoryTab=0;factoryErasing=factoryCopying=false;factory.notice="Stamp the actual "+std::to_string(line->parts.size())+"-machine line for "+line->name+". Feeders and the final dock run automatically; no food is copied.";}
void Interface::paintFactory(Position p){
 if(factoryTab==0&&isEnergyConduit(factoryTool)&&!factoryStamp&&!factoryErasing){factory.buildEnergyLink(p,conduitMedium(factoryTool));factorySelected=p;selectedEnergyMedium=conduitMedium(factoryTool);energyLinkSelected=true;return;}
 if(factoryErasing){factory.demolish(p);return;}if(factoryStamp){factory.stamp(*factoryStamp,p);return;}
 if(factoryTab!=0||factory.at(p)){selectMachine(p);return;}
 if(factory.build(p,factoryTool,factoryDirection)){energyLinkSelected=false;factorySelected=p;auto m=factory.at(p);if(m->kind==MachineKind::Feeder||isTastingDock(m->kind))m->automatic=false;if(sourceBrushConfigured&&(m->kind==MachineKind::Feeder||isDosingMachine(m->kind))){m->ingredient=sourceIngredient;m->dose=sourceDose;}if(sourceBrushConfigured&&m->kind==MachineKind::SeedHopper&&ingredient(sourceIngredient).category=="Produce")m->ingredient=sourceIngredient;referenceRecipe=0;batchSlot=componentIndex=0;dishName="Untitled dish";}

}
void Interface::stepFactory(){latticeSelected=-1;floorTelemetry.observe(factory,GetTime(),.44/factorySpeed);factory.step();floorTelemetry.observe(factory,GetTime(),.44/factorySpeed);}
void Interface::updateFactory(){
 auto mouse=pointer();bool panned=factoryPanning;bool inMap=CheckCollisionPointRec(mouse,factoryView)&&!CheckCollisionPointRec(mouse,factoryMiniMap);float wheel=GetMouseWheelMove();
 if(editFocus==1){auto before=librarySearch;editText(librarySearch,40);if(before!=librarySearch)libraryScroll.fill(0);}if(editFocus==2)editText(dishName,64);if(editFocus==3)editText(doseText,12);if(editFocus==4)editText(planName,64);
 if(IsKeyPressed(KEY_TAB)){if(editFocus==3)commitDose();editFocus=(editFocus+1)%5;}
 if(IsKeyPressed(KEY_ENTER)){if(editFocus==3)commitDose();editFocus=0;}
 if(IsKeyPressed(KEY_ESCAPE)){editFocus=0;factoryOverlay=0;factoryStamp.reset();factoryCopying=factorySelecting=factoryErasing=false;factoryTab=1;}
 if(factoryOverlay){modalScroll=std::clamp(modalScroll-wheel*40,0.f,std::max(0.f,modalContentHeight-300));}
 else{
  if(!editFocus){
   if(IsKeyPressed(KEY_SPACE)){factory.running=!factory.running;factoryAccumulator=0;}if(IsKeyPressed(KEY_PERIOD))stepFactory();
   if(IsKeyPressed(KEY_Q)){factoryCopying=!factoryCopying;factoryStamp.reset();factoryErasing=false;factory.notice="Drag a region on the floor to capture a reusable production plan.";}
   if(IsKeyPressed(KEY_B)){factoryOverlay=4;modalScroll=0;}
   if(IsKeyPressed(KEY_R)){factoryDirection=(factoryDirection+1)%4;if(factoryStamp)factoryStamp=Factory::rotatedBlueprint(*factoryStamp);else if(factoryTab==1&&factory.at(factorySelected)&&factory.at(factorySelected)->kind!=MachineKind::Wall)factory.rotate(factorySelected);}
   if(IsKeyPressed(KEY_DELETE)||IsKeyPressed(KEY_BACKSPACE))factory.demolish(factorySelected);
   if(IsKeyPressed(KEY_V))floorFlow=!floorFlow;
   if(IsKeyPressed(KEY_HOME))homeFactory();if(IsKeyPressed(KEY_F))fitFactory();
   bool command=IsKeyDown(KEY_LEFT_SUPER)||IsKeyDown(KEY_LEFT_CONTROL);if(command&&IsKeyPressed(KEY_Z)){factory.undo();floorTelemetry.clear();referenceRecipe=0;}if(command&&IsKeyPressed(KEY_S))saveFactoryCheckpoint();if(command&&IsKeyPressed(KEY_L))loadFactoryCheckpoint();
  }
  if(inMap){
   if(wheel){float tile=38*factoryZoom;factoryZoomAnchorWorld={factoryCamera.x+(mouse.x-factoryView.x-factoryView.width*.5f)/tile,factoryCamera.y+(mouse.y-factoryView.y-factoryView.height*.5f)/tile};factoryZoomAnchorMouse=mouse;factoryZoomTarget=std::clamp(factoryZoomTarget*std::pow(1.2f,wheel),.015f,3.f);factoryZooming=true;}
   int panButton=-1;if(IsMouseButtonPressed(MOUSE_BUTTON_MIDDLE))panButton=MOUSE_BUTTON_MIDDLE;else if(IsMouseButtonPressed(MOUSE_BUTTON_RIGHT))panButton=MOUSE_BUTTON_RIGHT;else if(IsMouseButtonPressed(MOUSE_BUTTON_LEFT)&&(IsKeyDown(KEY_LEFT_ALT)||IsKeyDown(KEY_RIGHT_ALT)))panButton=MOUSE_BUTTON_LEFT;
   if(panButton>=0){factoryPanning=true;factoryPanButton=panButton;factoryPanMoved=false;factoryPanMouse=mouse;float tile=38*factoryZoom;factoryPanWorld={factoryCamera.x+(mouse.x-factoryView.x-factoryView.width*.5f)/tile,factoryCamera.y+(mouse.y-factoryView.y-factoryView.height*.5f)/tile};}
   if(IsMouseButtonPressed(MOUSE_BUTTON_LEFT)&&!factoryPanning){editFocus=0;factoryDragStart=factoryPosition(mouse);factoryLastPaint=factoryDragStart;if(factoryCopying)factorySelecting=true;else if(!factoryStamp&&(factoryErasing||(factoryTab==0&&(!factory.at(factoryDragStart)||isEnergyConduit(factoryTool))))){factoryPainting=true;paintFactory(factoryDragStart);}}
  }else{
   for(int i=0;i<2;i++)if(CheckCollisionPointRec(mouse,libraryBodies[i]))libraryScroll[i]=std::clamp(libraryScroll[i]-wheel*36,0.f,std::max(0.f,libraryHeights[i]-libraryBodies[i].height));
   if(CheckCollisionPointRec(mouse,inspectorBody))inspectorScroll=std::clamp(inspectorScroll-wheel*36,0.f,std::max(0.f,inspectorHeight-inspectorBody.height));
   if(CheckCollisionPointRec(mouse,recipeBody))recipeScroll=std::clamp(recipeScroll-wheel*36,0.f,std::max(0.f,recipeHeight-recipeBody.height));
  }
  if(factoryZooming){float dt=std::clamp(GetFrameTime(),0.f,.1f),blend=1-std::exp(-18.f*dt);factoryZoom+=(factoryZoomTarget-factoryZoom)*blend;if(std::abs(factoryZoomTarget-factoryZoom)<std::max(.0002f,factoryZoomTarget*.0005f)){factoryZoom=factoryZoomTarget;factoryZooming=false;}if(!factoryPanning)factoryCamera={factoryZoomAnchorWorld.x-(factoryZoomAnchorMouse.x-factoryView.x-factoryView.width*.5f)/(38*factoryZoom),factoryZoomAnchorWorld.y-(factoryZoomAnchorMouse.y-factoryView.y-factoryView.height*.5f)/(38*factoryZoom)};}
  if(factoryPanning&&factoryPanButton==MOUSE_BUTTON_RIGHT){float dx=mouse.x-factoryPanMouse.x,dy=mouse.y-factoryPanMouse.y;if(dx*dx+dy*dy>25)factoryPanMoved=true;}
  if(IsMouseButtonReleased(MOUSE_BUTTON_RIGHT)){bool clickSelect=factoryPanButton==MOUSE_BUTTON_RIGHT&&!factoryPanMoved;if(clickSelect&&CheckCollisionPointRec(mouse,factoryView)&&!CheckCollisionPointRec(mouse,factoryMiniMap)){selectMachine(factoryPosition(mouse));editFocus=0;}}
  if(factoryPanning){float dx=mouse.x-factoryPanMouse.x,dy=mouse.y-factoryPanMouse.y;if(dx*dx+dy*dy>25)factoryPanMoved=true;if(factoryPanButton>=0&&IsMouseButtonDown(factoryPanButton)){float tile=38*factoryZoom;factoryCamera={factoryPanWorld.x-(mouse.x-factoryView.x-factoryView.width*.5f)/tile,factoryPanWorld.y-(mouse.y-factoryView.y-factoryView.height*.5f)/tile};if(factoryZooming){float zoomTile=38*factoryZoom;factoryZoomAnchorWorld={factoryCamera.x+(factoryZoomAnchorMouse.x-factoryView.x-factoryView.width*.5f)/zoomTile,factoryCamera.y+(factoryZoomAnchorMouse.y-factoryView.y-factoryView.height*.5f)/zoomTile};}}else{factoryPanning=false;factoryPanButton=-1;}}
  if(!editFocus&&!factoryPanning){float pan=10*GetFrameTime()/factoryZoom,oldX=factoryCamera.x,oldY=factoryCamera.y;if(IsKeyDown(KEY_LEFT))factoryCamera.x-=pan;if(IsKeyDown(KEY_RIGHT))factoryCamera.x+=pan;if(IsKeyDown(KEY_UP))factoryCamera.y-=pan;if(IsKeyDown(KEY_DOWN))factoryCamera.y+=pan;if(factoryZooming&&(oldX!=factoryCamera.x||oldY!=factoryCamera.y)){float tile=38*factoryZoom;factoryZoomAnchorWorld={factoryCamera.x+(factoryZoomAnchorMouse.x-factoryView.x-factoryView.width*.5f)/tile,factoryCamera.y+(factoryZoomAnchorMouse.y-factoryView.y-factoryView.height*.5f)/tile};}}
  if(factoryPainting&&IsMouseButtonDown(MOUSE_BUTTON_LEFT)&&inMap&&!factoryPanning){auto target=factoryPosition(mouse);int budget=100;while(target!=factoryLastPaint&&budget-->0){Position next=factoryLastPaint;int dir;if(std::abs(target.x-next.x)>=std::abs(target.y-next.y)&&target.x!=next.x){dir=target.x>next.x?0:2;next.x+=target.x>next.x?1:-1;}else{dir=target.y>next.y?1:3;next.y+=target.y>next.y?1:-1;}if(isTransport(factoryTool)&&!factoryErasing){auto previous=factory.at(factoryLastPaint);if(previous&&previous->kind==factoryTool&&previous->dir!=dir){factory.snapshot();previous->dir=dir;factory.dirty=true;}factoryDirection=dir;}if(factoryErasing)factory.demolish(next);else if(isEnergyConduit(factoryTool)||!factory.at(next))factory.build(next,factoryTool,factoryDirection);factoryLastPaint=next;}}
 }
 if(IsMouseButtonReleased(MOUSE_BUTTON_LEFT)){
  if(editFocus==3)commitDose();editFocus=0;
  if(factoryOverlay){bool handled=false;for(auto it=hits.rbegin();it!=hits.rend();++it)if(CheckCollisionPointRec(mouse,it->bounds)){handled=true;if(it->enabled){auto action=it->action;action();}break;}if(!handled)factoryOverlay=0;}
  else if(inMap&&!factoryPanning&&!panned){auto p=factoryPosition(mouse);if(factorySelecting){factory.captureBlueprint(factoryDragStart,p,planName);factorySelecting=factoryCopying=false;factoryOverlay=4;modalScroll=0;}else if(!factoryPainting)paintFactory(p);}
  else if(!factoryPanning&&!panned){for(auto it=hits.rbegin();it!=hits.rend();++it)if(CheckCollisionPointRec(mouse,it->bounds)){if(it->enabled){auto action=it->action;action();}break;}}
  if(factorySelecting&&!inMap)factorySelecting=factoryCopying=false;factoryPainting=false;
 }
 if(IsMouseButtonReleased(MOUSE_BUTTON_RIGHT)&&factoryPanButton==MOUSE_BUTTON_RIGHT){factoryPanning=false;factoryPanButton=-1;}
 factoryCamera.x=float(clamp(factoryCamera.x,-999999,999999));factoryCamera.y=float(clamp(factoryCamera.y,-999999,999999));factoryHovered=factoryPosition(mouse);advanceFactory();floorTelemetry.observe(factory,GetTime(),.44/factorySpeed);
 if(mouse.x!=lastMouse.x||mouse.y!=lastMouse.y){tooltipTime=0;lastMouse=mouse;}else tooltipTime+=GetFrameTime();tooltip.clear();if(!factoryOverlay)for(auto it=hits.rbegin();it!=hits.rend();++it)if(CheckCollisionPointRec(mouse,it->bounds)){tooltip=it->tip;break;}
}
void Interface::advanceFactory(){if(factory.running){factoryAccumulator+=std::min(GetFrameTime(),.25f)*factorySpeed;int n=0;while(factoryAccumulator>=.55f&&n++<5){stepFactory();factoryAccumulator-=.55f;}}else factoryAccumulator=0;factorySaveTimer+=GetFrameTime();if(factory.dirty&&factorySaveTimer>.9f){if(factory.save()){factory.dirty=false;factorySaveTimer=0;}else{factorySaveTimer=0;factory.notice="Autosave could not be written. This workspace is still in memory.";}}}
